export const RAPID = [
  /* ── C++ internals ──────────────────────────────────────────────────── */
  { id: "c1", domain: "cpp", d: 2, tags: ["containers", "latency"],
    q: "std::vector::push_back is amortized O(1). Why is that a dangerous thing to say on a hot path?",
    a: "Amortized means the average over many calls. A single push_back that triggers reallocation allocates, copies or moves every element, and frees — unbounded work, and it lands on whichever call is unlucky.",
    edge: "The tail is the whole problem: a p99.9 latency budget cares about that one call, not the average. Fix it by reserving at startup, or by using a fixed-capacity container so the reallocation cannot happen at all. Note also that growth is geometric (typically 1.5x or 2x), so the reallocations get rarer but each one gets more expensive." },
  { id: "c2", domain: "cpp", d: 2, tags: ["move", "exceptions"],
    q: "Why does moving elements during vector growth require the move constructor to be noexcept?",
    a: "push_back gives the strong exception guarantee: if it throws, the vector is unchanged. If a move constructor throws halfway through relocating, the old buffer has already been cannibalised and there is no way back. So the implementation only moves when the move is noexcept; otherwise it copies.",
    edge: "The practical consequence: forget noexcept on your move constructor and your container silently copies instead of moving, which can be an enormous slowdown with no error anywhere. std::move_if_noexcept is the mechanism. Check with static_assert(std::is_nothrow_move_constructible_v<T>)." },
  { id: "c3", domain: "cpp", d: 3, tags: ["layout", "aliasing"],
    q: "What is the difference between std::vector<bool> and every other vector, and why does it matter?",
    a: "It is a specialization that packs bits, so it is not a container of bool. operator[] returns a proxy object, not a reference; &v[0] does not give you a bool*; and it does not satisfy the container requirements the rest of the library assumes.",
    edge: "The follow-up is what to use instead: std::vector<char> or std::vector<uint8_t> when you want addressable elements, std::bitset when the size is a compile-time constant, or a hand-rolled bitmap when you actually want the packing. It is widely considered a standardisation mistake — being able to say why is the point." },
  { id: "c4", domain: "cpp", d: 3, tags: ["object model", "virtual"],
    q: "What does a virtual call actually cost, and when is it not the thing to fix?",
    a: "Load the vptr from the object, load the function pointer from the vtable, then an indirect call. Two dependent loads plus a jump the predictor must guess. When the call site is monomorphic in practice, the indirect branch predictor gets it right and the cost is close to a direct call.",
    edge: "It is expensive when the site is megamorphic (many types interleaved, so the predictor thrashes) or when it blocks inlining of something tiny. The usual real cost is the lost inlining, not the jump. Before removing it, measure branch-misses at that site; and remember devirtualization can already remove it when the type is provable." },
  { id: "c5", domain: "cpp", d: 3, tags: ["lifetime", "UB"],
    q: "A function returns a std::string_view built from a std::string temporary. What happens?",
    a: "The temporary dies at the end of the full expression and the view dangles. Reading it is undefined behaviour, and it usually appears to work, because the freed memory still holds the old bytes.",
    edge: "This is the whole hazard class of non-owning views: string_view, span, and reference members. The rule to state is that a view must never outlive its owner, so views belong in parameters, rarely in return types, and almost never in members. ASan with the right settings catches some of these; a lifetime-bound annotation catches more at compile time." },
  { id: "c6", domain: "cpp", d: 2, tags: ["templates", "build"],
    q: "Why do heavily templated headers make builds slow, and what actually reduces it?",
    a: "Every translation unit that includes the header re-parses and re-instantiates the templates, and the linker then discards the duplicate instantiations. The work is multiplied by the number of translation units.",
    edge: "What helps, in order of effect: include less (forward declarations, pimpl at boundaries), instantiate less (extern template for the common instantiations), and measure with -ftime-trace rather than guessing which header is the problem. Precompiled headers and unity builds treat the symptom. Modules address the cause but adoption is uneven." },
  { id: "c7", domain: "cpp", d: 4, tags: ["allocation", "latency"],
    q: "You have removed every new and delete from the hot path. Where might it still allocate?",
    a: "std::function when the callable exceeds the small-object buffer; std::string above the small-string capacity; any container that grows; std::shared_ptr's control block; exceptions themselves; std::regex; and iostreams. Some of these have no configurable bound.",
    edge: "The way to be certain is not to read the code but to prove it: override global operator new to abort, or run with a heap-tracking allocator, and assert zero allocations across the hot path in a test. That test is the deliverable — reasoning about it is not enough." },
  { id: "c8", domain: "cpp", d: 3, tags: ["atomics", "layout"],
    q: "Two atomics used by two different threads sit next to each other in a struct. What is wrong?",
    a: "False sharing. They fall in the same cache line, so every write by one thread invalidates the line in the other's cache, and two logically independent variables serialise on the coherence protocol.",
    edge: "Fix by padding each to its own line — alignas(std::hardware_destructive_interference_size), or alignas(64) when you want a fixed number. The measurable symptom is a huge jump in cache-coherence traffic with no change in instruction count, which is why counters and not the source are what tell you." },
  { id: "c9", domain: "cpp", d: 4, tags: ["UB", "optimizer"],
    q: "Why can a signed integer overflow check that reads perfectly sensibly be deleted by the compiler?",
    a: "Signed overflow is undefined, so the compiler may assume it never happens. A check written as `if (a + b < a)` is then provably false and gets removed — the check depends on the very behaviour the standard says cannot occur.",
    edge: "Write the check without relying on the overflow: compare against limits before the operation, use __builtin_add_overflow, or do the arithmetic in an unsigned type where wraparound is defined. -fwrapv makes it defined but ties you to that flag. UBSan finds these at run time; the deleted-check symptom is 'it works at -O0 and fails at -O2'." },
  { id: "c10", domain: "cpp", d: 2, tags: ["object model"],
    q: "When does a destructor NOT run for an object you created?",
    a: "If the constructor throws (the object never existed, though completed members and bases are destroyed); if you allocate with placement new and never call the destructor explicitly; if the program calls std::abort, _exit, or std::terminate; if the object is leaked; and for a derived object deleted through a base pointer with a non-virtual destructor, which is undefined behaviour.",
    edge: "The last one is the interview answer. The follow-up is when a non-virtual destructor is fine: when nothing ever deletes polymorphically, which you enforce by making the base destructor protected and non-virtual." },
  { id: "c11", domain: "cpp", d: 3, tags: ["initialization"],
    q: "What is the static initialization order fiasco, and what is the standard fix?",
    a: "Non-local objects with dynamic initialization in different translation units have no defined relative order, so one can be used before it is constructed. The failure is order-dependent and often only appears after an unrelated link-order change.",
    edge: "The fix is a function-local static — construction happens on first use, and since C++11 it is thread-safe (the compiler emits a guard variable). The cost is a guard check on every access, which matters only if it is genuinely hot. Destruction order at exit has the mirror problem, which is why some long-lived singletons deliberately leak." },
  { id: "c12", domain: "cpp", d: 4, tags: ["aliasing", "optimizer"],
    q: "What does the strict aliasing rule let a compiler assume, and how do you reinterpret bytes legally?",
    a: "Two pointers of unrelated types may be assumed not to point at the same object, so the compiler can keep a value in a register across a store through a different type. Casting a float* to an int* and dereferencing breaks that assumption and is undefined.",
    edge: "The legal ways are std::bit_cast (C++20), memcpy (which compilers recognise and turn into a single move), or going through char*/std::byte, which may alias anything. -fno-strict-aliasing disables the assumption at a real optimization cost. A union type-pun is legal in C, and formally not in C++, though most compilers support it." },

  /* ── Systems & OS ───────────────────────────────────────────────────── */
  { id: "s1", domain: "sys", d: 2, tags: ["syscall", "latency"],
    q: "Why is clock_gettime usually not a system call, and why should you still not put it in the innermost loop?",
    a: "The vDSO maps kernel code and a shared time page into user space, so the common clocks are read with an ordinary function call and no ring transition. Measured on a laptop in this project's perf track it was roughly 27 ns, against about 12 ns for a bare rdtsc.",
    edge: "Tens of nanoseconds is nothing next to a syscall and everything inside a loop measured in nanoseconds. Time the region, not the iteration; or use rdtsc with a calibration, remembering it needs serialisation (lfence/rdtscp) to not be reordered, and that it counts a constant reference frequency rather than the core clock." },
  { id: "s2", domain: "sys", d: 3, tags: ["memory", "latency"],
    q: "You malloc a large buffer and the first write to each page is slow. Why, and what do you do about it?",
    a: "malloc returns virtual address space; the physical pages are not mapped until first touch, so each first write takes a page fault. The cost lands on whoever touches it first, which on a hot path is the worst possible time.",
    edge: "Pre-fault at startup by writing one byte per page, or use MAP_POPULATE, and mlock if the pages must never be reclaimed. Huge pages reduce both the number of faults and TLB pressure. The measurement that proves it is minor-faults from perf stat or /proc/self/stat, before and after." },
  { id: "s3", domain: "sys", d: 3, tags: ["scheduler", "latency"],
    q: "A thread pinned to an isolated core still shows a periodic multi-microsecond stall. What are the candidates?",
    a: "The scheduler tick if the core is not nohz_full; interrupts that were never routed away; an IPI such as a TLB shootdown from another thread's munmap; RCU callbacks; the SMT sibling competing for the core's resources; a frequency or C-state transition; and page faults or NUMA migrations.",
    edge: "The point is to name a method, not a list: measure with an idle-loop histogram to confirm the stall is real, then attribute it — /proc/interrupts before and after, ftrace or perf sched, and turnstile counters. The single most common answer in practice is 'the interrupts were never actually moved', because setting smp_affinity does not migrate already-bound interrupts." },
  { id: "s4", domain: "sys", d: 2, tags: ["network"],
    q: "Why does disabling Nagle's algorithm matter for a request-response protocol?",
    a: "Nagle holds a small write until the previous unacknowledged data is acknowledged, so it batches small sends. Combined with delayed acknowledgements on the peer, a small request can wait for the peer's delayed-ACK timer — historically tens of milliseconds — before it goes out.",
    edge: "TCP_NODELAY turns it off. The subtlety worth adding is that the pathology needs both sides: Nagle on the sender and delayed ACK on the receiver. Also, turning it off means you now own coalescing, so a chatty protocol that sends header and body separately will put two packets on the wire." },
  { id: "s5", domain: "sys", d: 3, tags: ["io", "latency"],
    q: "When is busy-polling a socket the right answer, and what does it actually cost?",
    a: "When the arrival rate is high enough that a wake-up would dominate the work, and a core is genuinely spare. It removes the interrupt, the softirq, the scheduler wake-up and the context switch from the path, which is the microsecond-scale tail.",
    edge: "It costs a fully burned core, more power and heat, and it makes the machine worse at everything else. It also stops helping once you are bounded by the NIC or the wire. The honest framing is that you are buying determinism with a core, and the question to ask back is what the arrival distribution looks like." },
  { id: "s6", domain: "sys", d: 4, tags: ["memory"],
    q: "What is a TLB shootdown and why can one thread's munmap hurt an unrelated thread?",
    a: "When a mapping changes, every core that might have cached that translation must invalidate it. The initiating core sends an inter-processor interrupt and waits for the others to acknowledge. Cores doing unrelated work take the interrupt and the stall.",
    edge: "This is why long-lived low-latency processes avoid unmapping in steady state: allocate up front and never give memory back. It is also an argument for huge pages, which reduce the number of translations, and for per-thread arenas that do not share mappings. It shows up as an unexplained correlated stall across threads." },
  { id: "s7", domain: "sys", d: 3, tags: ["timing"],
    q: "You need to know whether the network or your process is slow. What do you instrument?",
    a: "Hardware timestamps. The NIC stamps arrival (SO_TIMESTAMPING); you stamp when the application reads it, after decode, after the decision, and at the write. Differences between adjacent stamps attribute the latency to a stage.",
    edge: "An application-level timestamp on read includes the kernel stack and any time your thread was not scheduled, so it cannot distinguish 'the network was slow' from 'we were not running'. Comparing stamps across machines additionally needs disciplined clocks — PTP, not NTP, at this resolution." },
  { id: "s8", domain: "sys", d: 2, tags: ["memory"],
    q: "What does an uncontended mutex actually cost, and when does that change?",
    a: "One atomic read-modify-write to take it and one to release: tens of nanoseconds, no system call. The futex syscall and the context switch only happen when a thread has to wait.",
    edge: "So the folklore that a mutex is microseconds is about contention, not locking. Under contention the choice is between sleeping (a syscall and a context switch, but the core is free) and spinning (no syscall, but a burned core and possible priority inversion). Neither is free; which is right depends on the expected wait against the cost of a context switch." },

  /* ── Architecture ───────────────────────────────────────────────────── */
  { id: "a1", domain: "arch", d: 2, tags: ["cache"],
    q: "Why is a linked list traversal so much slower than an array traversal of the same length?",
    a: "The array is contiguous, so the prefetcher predicts the stride and the loads overlap. Each list node's address is only known after the previous load returns, so the misses serialise: total time is the number of nodes times the full memory latency.",
    edge: "The name for what you lost is memory-level parallelism. Prefetching does not fix it because you cannot know the address early. The fixes are structural: pack nodes into an arena so they are contiguous, or traverse several independent chains at once so their misses overlap." },
  { id: "a2", domain: "arch", d: 3, tags: ["branches"],
    q: "When does replacing a branch with a conditional move make things worse?",
    a: "When the branch is predictable. A predicted branch costs nearly nothing and lets the core speculate past it; a cmov turns control dependence into a data dependence, so the result must wait for the condition and the dependent chain gets longer.",
    edge: "Branchless wins when the branch is unpredictable — roughly, data-dependent and close to random — and both sides are cheap. It also wins when you need constant time for security reasons. Decide with branch-misses from perf, and check the compiler has not already made the choice for you." },
  { id: "a3", domain: "arch", d: 3, tags: ["memory model"],
    q: "Why is acquire/release nearly free on x86 but not on AArch64?",
    a: "x86 is total-store-order: loads are not reordered with loads, stores not with stores, and only store-to-load forwarding is relaxed. So an acquire load and a release store need no fence instruction, just a compiler barrier. AArch64 is weakly ordered, so those become LDAR and STLR, which do real work.",
    edge: "Two things follow. First, code that is correct only by accident on x86 breaks on ARM, which is why the model and not the platform is what you reason about. Second, even on x86 a seq_cst store costs a full barrier (usually xchg), so seq_cst is not free there either." },
  { id: "a4", domain: "arch", d: 4, tags: ["memory model"],
    q: "Describe the store-buffer litmus test and what it proves.",
    a: "Two threads: each stores 1 to its own variable then loads the other's. With relaxed or plain accesses both can read 0 — impossible under any interleaving of the program order. The store buffer lets each store sit unpublished while the load goes ahead.",
    edge: "It proves that sequential consistency is not free even on x86: this is precisely the reordering TSO permits, and preventing it needs a full fence between the store and the load. It is the concrete demonstration that 'x86 is strongly ordered' does not mean 'x86 is sequentially consistent'." },
  { id: "a5", domain: "arch", d: 3, tags: ["cache"],
    q: "Your working set fits in L2 but the code runs at memory speed. What would you suspect?",
    a: "Conflict misses from a bad stride — the access pattern maps many hot lines to the same set, so they evict each other while most of the cache sits idle. A power-of-two stride over an array of structures is the classic cause.",
    edge: "Diagnose by changing the stride or padding the structure by one element and watching the miss rate move; a cache is typically 8- to 16-way, so it takes only a handful of colliding addresses. The other candidates are false sharing (check coherence counters) and TLB pressure (check dTLB misses) — the point is that 'fits in cache' is about capacity, and capacity is only one of three miss types." },
  { id: "a6", domain: "arch", d: 2, tags: ["counters"],
    q: "A change cut instruction count by 20% but the wall time did not move. What does that tell you?",
    a: "The loop was not throughput-bound on the front end or the ALUs. Time is being spent waiting — on memory, on a dependent chain, or on branch mispredictions — so removing work that was already overlapping with the wait changes nothing.",
    edge: "This is why instructions and cycles are read together: IPC tells you which regime you are in. Low IPC with high cache misses points at memory; low IPC with clean caches points at a latency chain or mispredicts. The general lesson is that instruction count is not a proxy for time." },
  { id: "a7", domain: "arch", d: 4, tags: ["cache", "atomics"],
    q: "Why can an atomic increment on an uncontended cache line still be much slower than a plain increment?",
    a: "A read-modify-write must own the line exclusively and must not be reordered around, so it locks the line for the duration and drains enough of the pipeline to give the required ordering. Even with no other thread involved, that serialisation is real.",
    edge: "Under contention it is far worse: the line ping-pongs between cores, each transfer costing a coherence round trip. The mitigations are to not share the counter (per-core counters summed on read), to batch updates, or to use relaxed ordering when you genuinely only need atomicity and not ordering." },

  /* ── Compilers ──────────────────────────────────────────────────────── */
  { id: "k1", domain: "compiler", d: 2, tags: ["optimizer"],
    q: "Why will the compiler not vectorise a loop that sums an array of doubles, and what changes that?",
    a: "Floating-point addition is not associative, so reassociating the sum changes the result. Vectorising means summing partial lanes and combining them, which is a reassociation, so it is forbidden unless you allow it.",
    edge: "You allow it with -ffast-math (too blunt: it also assumes no NaNs and no infinities), with -fassociative-math, or locally with #pragma clang fp reassociate(on). The disciplined answer is to reassociate deliberately — write the multiple-accumulator version yourself so the numerics are explicit and the code does not depend on a flag." },
  { id: "k2", domain: "compiler", d: 3, tags: ["aliasing"],
    q: "A function takes two pointers and the generated code reloads a value you know is unchanged. Why?",
    a: "The compiler cannot prove the pointers do not alias, so a store through one may have changed what the other points to, and the value must be reloaded after every such store.",
    edge: "Fix by giving it the information: restrict (or __restrict) asserts no aliasing and is a promise you must keep; copying to a local makes the non-aliasing structural; or restructure so the store and the load are on distinct types. Verify by reading the assembly before and after — this is one of the few optimizations where the source change is invisible and the object code is not." },
  { id: "k3", domain: "compiler", d: 3, tags: ["debugging"],
    q: "A bug appears at -O2 and not at -O0. What is your first hypothesis and how do you narrow it?",
    a: "Undefined behaviour that the optimizer exploited. At -O0 the UB happened to do something benign; at -O2 an assumption derived from it deleted or reordered code.",
    edge: "Narrow it by running UBSan and ASan first — they find most of these directly. If it survives, bisect the optimizer rather than the source: -opt-bisect-limit=N to find the pass that changes behaviour, or disable passes one at a time. A miscompilation is much rarer than UB, so the burden of proof is on the compiler being wrong." },
  { id: "k4", domain: "compiler", d: 3, tags: ["inlining"],
    q: "What does inlining actually buy, and when does more of it make code slower?",
    a: "It removes call overhead, but the real win is the optimization it unlocks: constants propagate into the body, the body's code merges with the caller's, and dead branches disappear. That is usually worth more than the call itself.",
    edge: "It hurts when it bloats the instruction footprint past the instruction cache or the micro-op cache, so the front end starts missing. It also lengthens compile time superlinearly. The symptom of over-inlining is more instructions retired and worse i-cache miss rate at the same work; -O3 versus -O2 regressions are often exactly this." },
  { id: "k5", domain: "compiler", d: 4, tags: ["SSA"],
    q: "What is a phi node and why does SSA need one?",
    a: "Static single assignment gives every value exactly one definition. Where control flow merges and a variable could have come from either predecessor, there is no single definition, so a phi node names the merged value and selects by which edge was taken.",
    edge: "The follow-up is that phi nodes are not real instructions — they must be eliminated before code generation, by inserting copies on the incoming edges. Doing that correctly in the presence of critical edges and overlapping live ranges is the lost-copy and swap problem, and is why the destruction of SSA is harder than its construction." },
  { id: "k6", domain: "compiler", d: 3, tags: ["debug info"],
    q: "Why can a debugger show the wrong line in optimized code, and is that a bug?",
    a: "Instructions from different source lines are scheduled together, and code is moved, merged, split and deleted. A single instruction can correspond to several source lines or none, so any single line the debugger shows is an approximation.",
    edge: "It is not a bug in general, but debug-info loss is a real class of compiler bug: a pass that drops a location where it could have kept one. llvm's debugify is the tool that finds it — inject synthetic locations, run the pass, and report what disappeared. The distinction between 'inherently ambiguous' and 'this pass lost it' is the answer." },

  { id: "k7", domain: "compiler", d: 2, tags: ["front end"],
    q: "Walk the stages from source text to an executable, and say what each one can and cannot catch.",
    a: "Lexing turns characters into tokens and catches only malformed tokens. Parsing builds a tree and catches grammar errors. Semantic analysis resolves names and types and catches the errors people actually make. Then IR generation, target-independent optimization, instruction selection, register allocation, scheduling, assembly and linking.",
    edge: "The follow-up is which stage a given error comes from — an undeclared identifier is semantic, not syntactic, and a missing symbol is the linker, not the compiler. The other is what SURVIVES: types are largely gone by the IR, and by the assembler there are no variables at all, which is why debug info has to be carried alongside rather than recovered." },
  { id: "k8", domain: "compiler", d: 3, tags: ["front end"],
    q: "Why is C++ hard to parse compared with most languages?",
    a: "The grammar is not context-free in practice: whether `A * B;` is a multiplication or a pointer declaration depends on whether A names a type, which requires having already done name lookup. Templates make it worse, because `A<B>(c)` is ambiguous until you know whether A is a template.",
    edge: "This is the lexer hack: the parser feeds the symbol table back into the lexer so it can classify identifiers as type-names. It is why C++ front ends interleave parsing and semantic analysis instead of running them as clean phases, and why `typename` and `template` disambiguators exist in dependent contexts — you are manually supplying information the parser cannot derive yet." },
  { id: "k9", domain: "compiler", d: 3, tags: ["dataflow"],
    q: "What does a dataflow analysis compute, and what makes one sound?",
    a: "It propagates facts over the control-flow graph until a fixed point — liveness backwards, reaching definitions forwards. Soundness means the result is conservative in the safe direction: it may claim a variable is live when it is not, but must never claim it is dead when it is.",
    edge: "The follow-up is termination: the lattice must have finite height and the transfer functions must be monotone, or the iteration may not converge. The practical consequence is that any analysis over an unbounded domain (like constant ranges) needs widening to force termination, and widening is where precision gets thrown away." },
  { id: "k10", domain: "compiler", d: 4, tags: ["regalloc"],
    q: "Register allocation is graph colouring. What happens when the graph is not colourable?",
    a: "You spill: pick a live range, store it to the stack, and reload at each use, which splits it into short ranges that interfere with less. Then rebuild the interference graph and try again.",
    edge: "The interesting part is the choice of what to spill — a good heuristic weights by use frequency divided by live-range length, so you spill something rarely used and long-lived, never something in the innermost loop. The follow-up is that real allocators are not pure colouring: linear-scan trades quality for compile speed, and both must respect pre-coloured registers from the calling convention and from instructions that demand specific registers." },
  { id: "k11", domain: "compiler", d: 3, tags: ["optimizer"],
    q: "What is the difference between a canonicalization and an optimization, and why does the distinction matter?",
    a: "A canonicalization rewrites equivalent forms into one chosen representative — `x * 2` to `x << 1`, or normalizing comparison direction — without necessarily making anything faster. An optimization makes the code better. Canonicalization exists so later passes have fewer patterns to match.",
    edge: "It matters because it explains pass ordering: canonicalize early so the analyses and rewrites downstream see one shape instead of five. It also explains why an apparent pessimization mid-pipeline is fine — the IR after instcombine is not meant to be good code, it is meant to be regular. Reading optimized IR without knowing this leads people to file bugs against canonicalization." },
  { id: "k12", domain: "compiler", d: 4, tags: ["loops"],
    q: "What is a loop-carried dependence and why does it decide whether a loop vectorises?",
    a: "A dependence where an iteration reads a value written by an earlier iteration. Vectorising executes several iterations at once, so a dependence with a distance shorter than the vector width would be violated — the hardware would read a value that has not been written yet.",
    edge: "The distinction to draw is the direction. `a[i] = a[i-1] + 1` is a true dependence at distance 1 and blocks vectorisation entirely. `a[i] = a[i+1] + 1` is an anti-dependence and is often still vectorisable with care. And a reduction — `sum += a[i]` — is a dependence the compiler CAN break, but only by reassociating, which for floating point needs your permission." },
  { id: "k13", domain: "compiler", d: 2, tags: ["linking"],
    q: "What is the difference between a static library, a shared library, and why does symbol interposition matter?",
    a: "A static archive is a bag of object files; the linker copies in the members that resolve undefined symbols. A shared library is loaded at run time and its symbols are resolved through indirection, which is what lets one definition serve many processes.",
    edge: "Interposition is the consequence: with default visibility, a symbol in a shared library can be replaced by an earlier definition at load time, so the compiler cannot inline it or even assume the call stays inside the library. That costs real performance, which is why libraries build with -fvisibility=hidden and export deliberately. It is also the mechanism behind LD_PRELOAD." },
  { id: "k14", domain: "compiler", d: 3, tags: ["testing"],
    q: "How would you test that an optimization pass is correct?",
    a: "Three layers. Lit and FileCheck tests pin the IR before and after on small inputs, which catches the intended transform regressing. A verifier run after the pass catches malformed IR. And differential testing — compile a large corpus with and without the pass and compare behaviour — catches what the small tests do not.",
    edge: "The strongest tool is a random program generator with a translation-validation or differential oracle: Csmith-style fuzzing with the pass on and off finds miscompiles no hand-written test does. The follow-up worth having is that a pass must also preserve the analyses it claims to preserve; getting that wrong produces a bug in a completely different pass, which is why the pass manager's invalidation model exists." },
  { id: "k15", domain: "compiler", d: 4, tags: ["undefined behaviour"],
    q: "Why does the compiler get to assume undefined behaviour never happens, and what does that buy?",
    a: "The standard imposes no requirements on a program that executes UB, so the compiler may assume any path containing it is unreachable and propagate that assumption backwards. That licenses removing null checks after a dereference, assuming loops terminate, and assuming signed arithmetic does not overflow.",
    edge: "What it buys is real: the no-overflow assumption is what lets `i` in `for (int i = 0; i <= n; i++)` be promoted to a 64-bit induction variable without a wrap check, which enables strength reduction and vectorisation. The cost is that a bug in your code becomes a transformation you did not expect, so the answer to \"the compiler broke my code\" is almost always UBSan first." },

  /* ── Probability & statistics ───────────────────────────────────────── */
  { id: "p1", domain: "prob", d: 2, tags: ["expectation"],
    q: "Why is linearity of expectation the strongest tool in an interview, and where does it stop working?",
    a: "E[X + Y] = E[X] + E[Y] holds for any random variables at all — no independence needed. So any 'expected number of' question can be decomposed into indicators and added, however tangled the dependence.",
    edge: "It stops the moment the question asks for a variance or a probability rather than a mean: Var(X + Y) has a covariance term, and the dependence comes back. The related trap is Jensen — E[1/X] is not 1/E[X], and E[X²] exceeds E[X]² by exactly the variance." },
  { id: "p2", domain: "prob", d: 3, tags: ["waiting times"],
    q: "Expected fair-coin flips to see HH is 6, but to see HT is 4. Explain the difference in one sentence.",
    a: "HH can be destroyed by its own failure — one H in, a T sends you back to nothing — while HT overlaps itself, so a failed H leaves you exactly where you were. Self-overlapping patterns wait longer.",
    edge: "The mechanical version is the martingale argument: for a fair coin the expected wait is the sum of 2^k over every k where the pattern's first k characters equal its last k. HH overlaps at k=1 and k=2, giving 2+4=6; HT only at k=2, giving 4. That generalises to any pattern and any alphabet." },
  { id: "p3", domain: "prob", d: 3, tags: ["estimation"],
    q: "A Monte Carlo estimate is not precise enough. Why is 'run more paths' usually the wrong first move?",
    a: "The standard error goes as σ/√N, so halving the error costs four times the paths and one more digit costs a hundred times. Compute is the most expensive lever with the worst exponent.",
    edge: "Cheaper levers first: report the standard error at all (often it is already inside tolerance); antithetic variates; control variates, which cut variance by 1/(1−ρ²) — a control correlated at 0.95 is worth twenty times the paths; and common random numbers when comparing two configurations. Only then buy compute, and check the per-thread generators are actually independent." },
  { id: "p4", domain: "prob", d: 2, tags: ["bayes"],
    q: "A test is 99% accurate for a condition affecting 1 in 10,000. You test positive. Roughly what is the probability you have it?",
    a: "About 1%. Prior odds 1:9,999, likelihood ratio 99, so posterior odds about 99:9,999, near 1:101.",
    edge: "The base rate dominates because false positives are drawn from a pool ten thousand times larger. The transfer is the point: this is the same arithmetic as an alert with a low true-event rate or a rarely-firing trading signal — a detector with impressive accuracy can still be wrong nearly every time it fires." },
  { id: "p5", domain: "prob", d: 3, tags: ["statistics"],
    q: "A backtest shows a strong result. Name the artifacts that most often explain it.",
    a: "Multiple testing — two hundred variants at the 5% level gives about ten 'significant' by construction, and the reported one is the maximum over the search. Then look-ahead bias, survivorship, regime overfitting, and unmodelled costs.",
    edge: "These are testable rather than merely cautionary: hold out data you have never looked at, report how many variants were tried, replay through the same code path as production so look-ahead is structurally impossible, and check the result survives realistic spread and impact." },
  { id: "p6", domain: "prob", d: 3, tags: ["distributions"],
    q: "Why do people reach for Poisson for order or packet arrivals, and when is that wrong?",
    a: "Independent arrivals at a constant rate give a Poisson count and exponential, memoryless gaps. It is the natural first model and it makes the algebra easy.",
    edge: "It predicts variance equal to the mean. Real order flow and real packet arrivals are bursty and clustered, so the observed variance is much larger — a signal the model is wrong. Saying that, rather than applying it silently, is the answer; the practical consequence is that queues sized on Poisson assumptions under-provision for the burst." },
  { id: "p7", domain: "prob", d: 4, tags: ["estimation"],
    q: "What is the difference between the mean and the median of a latency distribution, and which do you report?",
    a: "Latency distributions are right-skewed with a long tail, so the mean sits above the median and is dragged by rare large values. The median describes the typical request; neither describes the tail.",
    edge: "Report percentiles — p50, p99, p99.9 — because the tail is what users and trading systems experience. Two further traps: percentiles do not average, so you cannot combine p99s across shards by taking their mean; and if every request fans out to ten services, the p99 of one service is hit by most requests." },

  /* ── HFT & markets ──────────────────────────────────────────────────── */
  { id: "h1", domain: "hft", d: 2, tags: ["microstructure"],
    q: "Why does a market maker care about queue position, beyond just filling sooner?",
    a: "Under time priority the back of the queue fills only when the level is nearly exhausted — which is exactly when there is real pressure and the price is about to move against you. Same price, systematically worse trades.",
    edge: "So queue position is a selection effect on which trades you get, not a convenience. In code this is why 'cancel and replace' and 'modify down' are different operations: increasing size or changing price usually loses priority, decreasing size usually keeps it, and a system that treats them alike throws away the asset." },
  { id: "h2", domain: "hft", d: 3, tags: ["microstructure"],
    q: "What is adverse selection and why is it the central cost of providing liquidity?",
    a: "Your resting order is a free option written to the market. It gets taken by whoever most wants that side — the better-informed counterparty — so your fills are conditioned on being wrong, not a random sample.",
    edge: "That is what the spread compensates for, alongside inventory risk and operating cost. It is measured with markouts: take the mid at your fill, then at one second, ten, sixty; if your buys are followed by the mid falling, that average is the cost per share. It also explains why cancel latency has direct economic value — you are withdrawing the option before it is exercised." },
  { id: "h3", domain: "hft", d: 3, tags: ["latency"],
    q: "Name the distinct mechanisms by which latency makes money. 'Faster is better' is not an answer.",
    a: "Three: taking a quote that has gone stale after a price moves elsewhere; cancelling your own quote before someone takes it stale; and reaching a newly-formed price level early to get queue position.",
    edge: "They stress different things. Taking is a winner-take-all race, so value is enormously convex in latency. Cancelling reduces a cost you already pay, so it is worth something even if you never win a race. And all three live in the tail, not the mean — a page fault or a lock at the wrong moment is what loses the trade, which is why the obsession is with jitter and p99.9." },
  { id: "h4", domain: "hft", d: 3, tags: ["market data"],
    q: "Market data arrives as sequenced UDP multicast. What does that choice hand to your code?",
    a: "Gap detection and recovery, because UDP drops and reorders; book state, because the stream is incremental so a gap invalidates everything after it; and startup, because you join mid-stream and must buffer increments while you fetch a snapshot.",
    edge: "The standard recovery is A/B arbitration — the same feed on two paths, take whichever copy arrives first — plus a retransmission channel and periodic snapshots. The judgement question is what to do while in a gap: most systems stop quoting rather than trade on a book known to be wrong. And monitor kernel drop counters, because a burst overflowing the receive buffer is silent." },
  { id: "h5", domain: "hft", d: 4, tags: ["microstructure"],
    q: "Why does the tick size matter so much to an engineer?",
    a: "The spread cannot be finer than one tick. When the tick binds — the spread sits at one tick nearly always — you can no longer compete by quoting a better price, because there is no better price.",
    edge: "Competition then moves entirely to queue position, which is to say to latency and to how you manage priority. That single structural fact is what turns a market-making problem into a systems-engineering problem, and it is the cleanest explanation of why these firms hire people who care about cache lines." },
  { id: "h6", domain: "hft", d: 3, tags: ["backtest"],
    q: "A backtest fills passive orders at the mid. What specifically is wrong?",
    a: "Passively you were granted a fill you would have had to earn by reaching the front of a queue and then having someone trade against you — and the simulation grants it precisely in the states where a real fill would have been adverse. Aggressively you have deleted the spread, which for a high-turnover strategy usually exceeds the modelled edge.",
    edge: "Increasing fidelity: cross the spread and add fees; model queue position from market-by-order data; add a latency model so decisions use the book as it was when the message arrived and orders land some microseconds later. The structural fix beats all of them — run the same code in backtest and production, driven by recorded data, so the simulation cannot see what the live system could not." },
  { id: "h7", domain: "hft", d: 2, tags: ["microstructure"],
    q: "What do effective spread, realized spread and price impact each measure?",
    a: "Effective spread is the cost against the mid at the moment of the trade. Realized spread is the same trade against the mid some interval later, so it is what the liquidity provider actually kept. The difference is price impact — the part the market took back.",
    edge: "Reporting only one of the three is how a strategy looks profitable and is not: a large effective spread with a near-zero realized spread means you captured the quoted spread and gave it all back to informed flow." },

  /* ── second pass: the follow-ups that separate depth from recall ────── */
  { id: "c13", domain: "cpp", d: 3, tags: ["move"],
    q: "Why does `return std::move(local)` make things worse?",
    a: "It turns the return expression into an xvalue rather than a prvalue naming a local, which disqualifies named return value optimisation. You have replaced a free elision with a guaranteed move.",
    edge: "Since C++17 elision of prvalues is mandatory, so `return T{};` requires no move constructor at all. NRVO for a named local stayed optional but every mainstream compiler does it. The one place std::move on return IS right is returning a member or a parameter, where elision was never available." },
  { id: "c14", domain: "cpp", d: 4, tags: ["templates"],
    q: "When is `T&&` not a forwarding reference?",
    a: "Whenever T is not being deduced at that parameter. A class template member using the class's own T, `std::vector<T>&&`, and any explicitly specified argument are all plain rvalue references.",
    edge: "The follow-up is why forwarding works at all: deduction gives T = U& for an lvalue and T = U for an rvalue, and reference collapsing turns `U& &&` into `U&`. Inside the function the parameter is a named variable and therefore an lvalue, which is why passing it on without std::forward silently copies." },
  { id: "c15", domain: "cpp", d: 3, tags: ["containers"],
    q: "Why can std::unordered_map never be as fast as a good flat hash map?",
    a: "The standard guarantees references to elements stay valid across rehashing and permits erasure during iteration. That forces separate chaining — an array of buckets each holding a linked list — so every element is its own allocation and every collision is a pointer chase.",
    edge: "The limit is the container's contract, not the implementation's quality. A flat open-addressing table is one load in the common case but moves elements, which the guarantee forbids. Also worth knowing: libstdc++ hashes integers with the identity function, so sequential keys cluster badly with a power-of-two bucket count." },
  { id: "c16", domain: "cpp", d: 3, tags: ["exceptions"],
    q: "Exceptions are described as zero-cost. What does that actually mean, and what still costs?",
    a: "Table-driven unwinding puts the information needed to unwind in side tables rather than in the code, so the path that does not throw executes no extra instructions. Throwing walks those tables, which is orders of magnitude slower than a return.",
    edge: "So `-fno-exceptions` buys code size and a design discipline, not throughput. The reason they are banned on a latency path is not the try block, which is free, but that a throw's cost is unbounded and data-dependent — table lookup, possibly a lock, then the destructor chain — inside a budget measured in hundreds of nanoseconds." },
  { id: "c17", domain: "cpp", d: 4, tags: ["ODR"],
    q: "Two translation units define the same struct differently. What happens?",
    a: "It links, and the linker keeps one arbitrarily. That is an ODR violation: undefined behaviour with no diagnostic. The symptom appears far from the cause — one side writing past what the other thinks is the end.",
    edge: "It usually arrives through flags rather than source: one file built with -DNDEBUG and a header whose struct gains a member under assertions. Defences are a consistent build, anonymous namespaces for translation-unit-local types, and -flto, which lets the linker see the mismatch. ASan detects the global case only." },
  { id: "s9", domain: "sys", d: 3, tags: ["memory"],
    q: "What does the OOM killer choose, and how do you keep a latency-critical process off the list?",
    a: "The kernel scores processes roughly by resident memory and kills the highest. A big process is the target even if it is not the one that grew.",
    edge: "You bias the score with oom_score_adj. The better answer is not to be in the situation: reserve and pre-fault at startup, mlock what must never be reclaimed, and disable swap for the process, so that memory pressure fails at initialisation rather than at the worst moment." },
  { id: "s10", domain: "sys", d: 3, tags: ["scheduler"],
    q: "What is the difference between SCHED_FIFO and SCHED_OTHER, and what is the risk?",
    a: "SCHED_OTHER is the ordinary fair scheduler. SCHED_FIFO is real-time: a runnable FIFO thread preempts every normal thread and runs until it blocks or yields.",
    edge: "The risk is that a busy-looping FIFO thread on a core with no other escape starves everything else including kernel threads, and you lose the machine. That is what sched_rt_runtime_us exists to bound. Pair it with an isolated core and a watchdog, and know that priority inversion becomes possible the moment a FIFO thread waits on a lock held by a normal one." },
  { id: "a8", domain: "arch", d: 4, tags: ["memory"],
    q: "What is a store buffer and which reordering does it permit on x86?",
    a: "A queue holding retired stores before they reach cache, so a store does not stall the pipeline. It permits exactly one reordering under TSO: a later load may complete before an earlier store to a different address becomes visible.",
    edge: "That single relaxation is the store-buffer litmus test — two threads each storing then loading the other's variable can both read zero, which no interleaving of program order allows. It is the concrete proof that 'x86 is strongly ordered' does not mean sequentially consistent, and why a seq_cst store needs a full fence even there." },
  { id: "a9", domain: "arch", d: 3, tags: ["pipeline"],
    q: "What is the cost of a branch misprediction, and why does it vary?",
    a: "The pipeline speculates down the predicted path; a mispredict discards that work and restarts fetch. The penalty is roughly the pipeline depth to the point of resolution — on modern cores in the region of fifteen to twenty cycles.",
    edge: "It varies because it is not just the flush: the correct path's instructions may not be in the instruction cache or the micro-op cache, and any loads on the wrong path may have polluted the data cache. Measure with branch-misses alongside cycles rather than assuming a fixed number — and remember a predictable branch costs essentially nothing, which is why replacing it with a cmov can be a loss." },
  { id: "k16", domain: "compiler", d: 3, tags: ["linking"],
    q: "What is symbol interposition and why do libraries build with -fvisibility=hidden?",
    a: "With default visibility, a symbol exported from a shared library can be replaced at load time by an earlier definition. So the compiler cannot inline such a call, or even assume it stays within the library.",
    edge: "That costs real performance on every cross-function call in the library. Hidden visibility plus explicit exports lets the compiler devirtualise and inline internally. It is also the mechanism behind LD_PRELOAD, which is why a library that wants to remain interposable — malloc, for instance — deliberately does not hide." },
  { id: "k17", domain: "compiler", d: 4, tags: ["testing"],
    q: "How would you find a miscompile you cannot reproduce in a small test?",
    a: "Reduce rather than guess. Bisect the pass pipeline with -opt-bisect-limit to find which transformation changes behaviour, then reduce the input with llvm-reduce or creduce against a script that checks for the wrong behaviour.",
    edge: "The reduction script is the part that matters and the part people write badly: it must return 'interesting' only for the actual miscompile, or the reducer happily reduces to a program that is merely undefined. Run UBSan on the reduced case before filing — a large fraction of suspected miscompiles are UB the optimizer was entitled to exploit." },
  { id: "p8", domain: "prob", d: 3, tags: ["estimation"],
    q: "You are asked to estimate something you have no data for. What does the interviewer score?",
    a: "The structure. Decompose into terms each defensible within a factor of two or three, state every assumption as an assumption, give a range rather than a point, and name the term you least trust.",
    edge: "The last part is the one people forget, and it is what separates a good answer from a lucky one. Errors in a product of independent estimates partly cancel rather than compounding, which is why decomposition beats a single guess — and why identifying the one term that dominates the error is more useful than refining the others." },
  { id: "p9", domain: "prob", d: 4, tags: ["statistics"],
    q: "A strategy shows a Sharpe of 2 in backtest. How long must it run live before you believe it?",
    a: "Years. The standard error of an estimated Sharpe is roughly the square root of (1 + S²/2)/T with T in years, so distinguishing S = 2 from zero at two standard errors needs on the order of a decade of data.",
    edge: "And that is the optimistic bound, because it assumes returns are independent and identically distributed. Autocorrelation and regime change make the effective sample much smaller than the calendar suggests. It is the quantitative reason out-of-sample discipline matters more than in-sample significance." },
  { id: "h8", domain: "hft", d: 3, tags: ["risk"],
    q: "Where do pre-trade risk checks belong, and what is the trade?",
    a: "On the path, before the order leaves — position limits, fat-finger price and size bounds, and a message-rate throttle. Anything checked after the order is on the wire is not a control.",
    edge: "Every check costs latency on the critical path, which is exactly what you are optimising, so the discipline is to make them branch-free and bounded: precomputed limits in registers or one cache line, integer comparisons, no lookups. Some firms push them into an FPGA for that reason. The one thing you never do is make the check optional under load." },
  { id: "h9", domain: "hft", d: 4, tags: ["microstructure"],
    q: "What is the difference between a fill you wanted and a fill you got, and how would you measure it?",
    a: "Markouts. Take the mid at the moment of your fill, then at one second, ten, sixty. If your buys are systematically followed by the mid falling, the flow is picking you off, and the average of that quantity is the cost per share.",
    edge: "The decomposition to state is effective spread minus realized spread equals price impact: what you captured at the trade, what you kept after the market moved, and the difference the market took back. A large effective spread with a near-zero realized spread means you captured the quote and gave it all back to informed flow." },
];

export const RAPID_BY_DOMAIN = DOMAINS.map((d) => ({
  ...d, items: RAPID.filter((r) => r.domain === d.id),
}));

export const rapidById = (id) => RAPID.find((r) => r.id === id);
